import {HOME_BUNDLE_SECTIONS,homeBundleSections,HOME_FIXED_SECTIONS,recommendBundleOffers} from '../mock-app/home-recommend-settings.js';
const limit=key=>key==='challenges'?Infinity:key==='pointUp'?8:6;
export function draftHomeSections(form){const saved=JSON.parse(form.querySelector('[name=fixedSections]')?.value||'[]'),mission=saved.find(row=>row.key==='missions'),fixed=saved.filter(row=>row.key!=='missions').map((row,index)=>({...row,order:index+1}));const rows=[...fixed,...[...form.querySelectorAll('[data-home-section]')].map((row,index)=>{const key=row.dataset.homeSection,attribute=row.querySelector('[name=bundleAttribute]')?.value||'',group=form.querySelector(`[data-home-offers="${key}"]`);return {key,title:row.querySelector('[name=sectionTitle]').value,enabled:true,kind:row.dataset.kind||undefined,moreLink:row.querySelector('[name=moreLink]').value,order:fixed.length+index+1,bundleAttribute:attribute,offerOrder:group?.dataset.attribute===attribute?[...group.querySelectorAll('[data-home-offer]')].map(item=>item.dataset.homeOffer):[],start:row.querySelector('[name=sectionStart]').value,end:row.querySelector('[name=sectionEnd]').value};})];if(mission)rows.splice(Math.max(fixed.length,Math.min(rows.length,mission.order-1)),0,mission);return rows.map((row,index)=>({...row,order:index+1}));}

export function homeOfferPositions(offers,settings,key,getAvailableOffers){return recommendBundleOffers(getAvailableOffers?getAvailableOffers(key):offers,settings,key).slice(0,limit(key));}
export function bubblePositions(row,settings,offers,esc,getAvailableOffers){const items=homeOfferPositions(offers,settings,row.sectionKey,getAvailableOffers),max=Number.isFinite(limit(row.sectionKey))?limit(row.sectionKey):Math.max(1,items.length,row.position||1);return Array.from({length:max},(_,i)=>`<option value="${i+1}" ${row.position===i+1?'selected':''}>${i+1}枠目：${esc(items[i]?.name||'表示する案件なし')}</option>`).join('');}
function offerRows(settings,offers,key,esc,getAvailableOffers){const matched=recommendBundleOffers(offers,settings,key),available=recommendBundleOffers(getAvailableOffers?getAvailableOffers(key):offers,settings,key),all=[...available,...matched.filter(item=>!available.some(o=>o.id===item.id))],actual=homeOfferPositions(offers,settings,key,getAvailableOffers),positions=new Map(actual.map((item,i)=>[item.id,i+1]));return all.map(item=>`<tr data-home-offer="${esc(item.id)}"><td><button class="home-sort-handle" type="button" draggable="true" aria-label="${esc(item.name)}を並べ替え" title="ドラッグで並べ替え・上下キーでも移動">⠿</button></td><td data-home-offer-position>${positions.has(item.id)?positions.get(item.id)+'枠目':'表示対象外・上限外'}</td><td><a href="../mock-app/#offer/${encodeURIComponent(item.id)}" target="_blank" rel="noopener">${esc(item.name)}</a><small class="tiny home-offer-id">${esc(item.id)}</small></td></tr>`).join('')||'<tr><td colspan="3" class="tiny">該当する案件がありません。</td></tr>';}
export function homeBundlePreview(settings,offers,esc,getAvailableOffers){return `<section class="panel home-bundle-preview"><h2>案件詳細の並べ替え</h2><p class="desc">指定バンドルの案件を表示しています。ハンドルをドラッグして順序を変更できます。変更を保存すると、この掲載枠だけに反映します。</p>${homeBundleSections(settings).map(key=>{const row=settings.sections.find(s=>s.key===key);return `<details data-home-preview="${key}"><summary><b data-home-preview-title>${esc(row.title)}</b> <span class="tiny" data-home-preview-attribute>${esc(row.bundleAttribute||'バンドル未設定')}</span></summary><div class="tbl"><table><thead><tr><th>並び替え</th><th>アプリの表示位置</th><th>案件名・案件ID</th></tr></thead><tbody data-home-sort="offers" data-home-offers="${key}" data-attribute="${esc(row.bundleAttribute||'')}">${offerRows(settings,offers,key,esc,getAvailableOffers)}</tbody></table></div></details>`;}).join('')}<p class="tiny">公開条件・掲載上限によりアプリに出ない案件は「表示対象外・上限外」と表示します。バンドルへの追加案件は末尾に入り、属性が外れた案件は一覧から外れます。吹き出しは案件を固定せず、並べ替え後の表示位置に付きます。</p></section>`;}
export function refreshHomeBundlePreview(form,offers,esc,getAvailableOffers,rebuildKey){const settings={sections:draftHomeSections(form)};if(rebuildKey==='all'){const panel=form.querySelector('.home-bundle-preview');const open=[...panel.querySelectorAll('details[open]')].map(item=>item.dataset.homePreview);panel.outerHTML=homeBundlePreview(settings,offers,esc,getAvailableOffers);for(const key of open){const details=form.querySelector(`[data-home-preview="${key}"]`);if(details)details.open=true;}}for(const key of homeBundleSections(settings)){const row=settings.sections.find(s=>s.key===key),group=form.querySelector(`[data-home-offers="${key}"]`),panel=form.querySelector(`[data-home-preview="${key}"]`);if(!group)continue;const count=form.querySelector(`[data-home-section="${key}"] [data-home-bundle-count]`);if(count)count.textContent=row.bundleAttribute?recommendBundleOffers(offers,settings,key).length+'件が一致':'未設定';panel.querySelector('[data-home-preview-title]').textContent=row.title;panel.querySelector('[data-home-preview-attribute]').textContent=row.bundleAttribute||'バンドル未設定';if(rebuildKey===key){group.innerHTML=offerRows(settings,offers,key,esc,getAvailableOffers);group.dataset.attribute=row.bundleAttribute;}else{const actual=homeOfferPositions(offers,settings,key,getAvailableOffers),positions=new Map(actual.map((item,i)=>[item.id,i+1]));for(const item of group.querySelectorAll('[data-home-offer]'))item.querySelector('[data-home-offer-position]').textContent=positions.has(item.dataset.homeOffer)?positions.get(item.dataset.homeOffer)+'枠目':'表示対象外・上限外';}}
for(const row of form.querySelectorAll('[data-home-bubble]')){const select=row.querySelector('[name=bubbleSection]'),position=row.querySelector('[name=bubblePosition]');const selected=select.value;select.innerHTML=homeBundleSections(settings).map(key=>`<option value="${key}" ${selected===key?'selected':''}>${esc(settings.sections.find(s=>s.key===key)?.title||key)}</option>`).join('');position.innerHTML=bubblePositions({sectionKey:select.value,position:Number(position.value)||1},settings,offers,esc,getAvailableOffers);}}
